detaileddescription.para:
>0テキストの長さ。


<0エラーが発生しました



in



復号化されるバイト配列。




inLen



バッファ入力の長さ。




out



PSSデータを含むアドレスへのポインター。




hash



メッセージに含まれるハッシュタイプ




mgf



マスク生成関数識別子




key



使用するrsakey



_Example_ ret=wc_InitRsaKey(&key,NULL);
if(ret==0){
ret=wc_InitRng(&rng);
}elsereturn-1;
if(ret==0){
ret=wc_RsaSetRNG(&key,&rng);
}elsereturn-1;
if(ret==0){
ret=wc_MakeRsaKey(&key,2048,WC_RSA_EXPONENT,&rng);
}elsereturn-1;
ret=wc_RsaPSS_Sign(digest,digestSz,pSignature,pSignatureSz,
WC_HASH_TYPE_SHA256,WC_MGF1SHA256,&key,&rng);
if(ret>0){
sz=ret;
}elsereturn-1;

ret=wc_RsaPSS_VerifyInline(pSignature,sz,pt,
WC_HASH_TYPE_SHA256,WC_MGF1SHA256,&key);
if(ret<=0)return-1;

wc_FreeRsaKey(&key);
wc_FreeRng(&rng);
